select A.TREE_ID treeId, A.PORTFOLIO_ID portfolioId, B.PORTFOLIO_NAME portfolioName,
E.FINPROD_ID finprodId, E.FINPROD_MARKET_ID finprodMarketId, E.FINPROD_ABBR finprodName, E.FINPROD_TYPE2 finprodType2,
case when #{ps} = #{PS_T100} then null else #{ps} end ps,
A.CCY ccy, nvl(F.TDY_ASSET_NETVALUE,0) productNetValue from MUTIPTL_PORTFOLIO_DETAIL A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY C ON B.PORTFOLIO_ID = C.PORTFOLIO_ID
LEFT JOIN FIN_PRODUCT E ON E.FINPROD_ID = #{finprodId}
LEFT JOIN PTL_PORTFOLIO_VALUATION F ON F.PORTFOLIO_ID = A.PORTFOLIO_ID AND F.CDATE <= to_date(#{ptlDate},'yyyy-mm-dd') -1 AND A.CCY = F.CCY
A.TREE_ID = #{portfolioTreeId} AND A.EFF_DATE <= to_date(#{ptlDate},'yyyy-mm-dd') AND C.USER_ID = #{userId}
AND A.PORTFOLIO_ID = #{portfolioId}
and A.PORTFOLIO_ID in
#{item}

select B.SEC_ACCT_ID
  from PTL_SEC_ACCT A
 INNER JOIN STL_SEC_ACCT_INFO B
    ON A.ACCT_NO = B.SEC_ACCT_ID
 WHERE A.PORTFOLIO_ID = #{portfolioId}
   AND B.TRD_ACCT_ID = #{acctNo}
   AND B.TRADE_PLACE = #{tradeMarket}
   AND B.SEC_ACCT_TYPE = 'SEC'
